def parse_metadata_block(body: str) -> dict:
    """Read the identity block back. Returns {} when absent.

    Uses the same innermost-well-formed-pair search as the writer
    (:func:`_metadata_bounds`), so a stray or unfinished marker quoted
    elsewhere in the body — before or after the real block — cannot feed
    fields into the parse, and a body with no complete pair reads as having
    no metadata at all.
    """
    if not body:
        return {}
    bounds = _metadata_bounds(body)
    if bounds is None:
        return {}
    start, end = bounds
    inner = body[start + len(METADATA_BEGIN) : end - len(METADATA_END)]
    fields: dict = {}
